"""CCAO-F part A: Domain 1 (Prompting and Task Execution), Domain 2 (Output Evaluation
and Validation) and Domain 3 (Product and Model Selection).

Written against the Claude Certified Associate - Foundations exam guide (version 1.0,
effective July 2026; weights 14% / 21% / 12% for these three domains) and checked in
October 2026 against the Claude Help Center (web search, research, extended thinking,
model and effort settings, file uploads, file creation, Projects, memory, context
windows) and the Claude platform docs (models overview, choosing a model, effort,
prompting best practices, reduce hallucinations, context windows).
Part B (data/ccao_b.py) owns the other four domains and the numbering from 1001.
The Exam-day strategy cheat-sheet section lives here; data/ccao.py moves it last.
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


